  "type": "DIRECT",                            // optional · default "DIRECT" · Allowed (case-sensitive): "DIRECT" | "TRAVEL_AGENT"

  // required when type is "TRAVEL_AGENT", otherwise optional · max 200 chars
  // "companyName": "Whitfield Travel Group",

  "status": "LEAD",                            // optional · default "LEAD" · Allowed (case-sensitive): "LEAD" | "ACTIVE" | "VIP" | "INACTIVE"
  // Where the relationship stands. Distinct from leadStage, which is where the deal stands.

  "firstName": "Marcus",                       // required · max 100 chars

  "lastName": "Reyes",                         // required · max 100 chars

  "email": "marcus.reyes@example.com",         // optional · valid email, stored lowercase

  "phone": "+1 555 0142",                      // optional · max 40 chars, free-form

  // optional · ISO date (YYYY-MM-DD). Drives VIP birthday reminders.
  // "birthday": "1979-04-12",

  // optional · UUID of an airport row, not a code. Airports are their own
  // module, and a code typed into a box is how a home airport ends up
  // matching nothing. Send null to clear it. 400 if the id is unknown or archived.
  // "homeAirportId": "00000000-0000-4000-8000-000000000000",

  "leadSource": "REFERRAL",                    // optional · default "DIRECT" · Allowed (case-sensitive): "DIRECT" | "TRAVEL_AGENT" | "FACEBOOK_GROUP_1" | "FACEBOOK_GROUP_2" | "REFERRAL" | "WEBSITE" | "OTHER"

  "leadStage": "NEW",                          // optional · default "NEW" · Allowed (case-sensitive): "NEW" | "CONTACTED" | "QUOTED" | "NEGOTIATING" | "BOOKED" | "LOST"

  // optional · UUID of the owning broker.
